use clap::{Parser, Subcommand};
use colored::*;

mod commands;
mod types;
mod utils;

use commands::global_context::GlobalContext;

#[derive(Parser)]
#[command(name = "hitch")]
#[command(about = "A CLI tool for managing environment-specific git branches and metadata")]
#[command(version = "1.0.0")]
#[command(author = "Martin Page")]
struct Cli {
    /// Print detailed step-by-step logs for commands
    #[arg(long, global = true)]
    verbose: bool,

    /// Skip automatic pushes when metadata is committed
    #[arg(long, global = true)]
    no_push: bool,

    #[command(subcommand)]
    command: Commands,
}

#[derive(Subcommand)]
enum Commands {
    /// Initialize hitch metadata in the current git repository
    Init(commands::init::InitCommand),
    /// Add a new environment to hitch configuration
    Add(commands::add::AddCommand),
    /// Remove an environment from hitch configuration
    Remove(commands::remove::RemoveCommand),
    /// Promote a branch to an environment for deployment
    Promote(commands::promote::PromoteCommand),
    /// Demote a branch from an environment
    Demote(commands::demote::DemoteCommand),
    /// Rebuild an environment by merging its branches
    Rebuild(commands::rebuild::RebuildCommand),
    /// Show the status of Hitch environments and branches
    Status(commands::status::StatusCommand),
    /// Lock an environment to prevent changes
    Lock(commands::lock::LockCommand),
    /// Unlock an environment to allow changes
    Unlock(commands::unlock::UnlockCommand),
    /// Guard against commits to environment branches (for pre-commit hooks)
    Guard(commands::guard::GuardCommand),
}

fn main() -> Result<(), Box<dyn std::error::Error>> {
    // Initialize colored output
    colored::control::set_override(true);

    let cli = Cli::parse();

    // Create global context with flags
    let context = GlobalContext::new(cli.verbose, cli.no_push)?;

    // Execute the appropriate command
    match cli.command {
        Commands::Init(args) => commands::init::run(args, &context),
        Commands::Add(args) => commands::add::run(args, &context),
        Commands::Remove(args) => commands::remove::run(args, &context),
        Commands::Promote(args) => commands::promote::run(args, &context),
        Commands::Demote(args) => commands::demote::run(args, &context),
        Commands::Rebuild(args) => commands::rebuild::run(args, &context),
        Commands::Status(args) => commands::status::run(args, &context),
        Commands::Lock(args) => commands::lock::run(args, &context),
        Commands::Unlock(args) => commands::unlock::run(args, &context),
        Commands::Guard(args) => commands::guard::run(args, &context),
    }
}

use chrono::{DateTime, Utc};
use serde::{Deserialize, Serialize};

/// Environment configuration as defined in hitch.json
#[derive(Debug, Clone, Serialize, Deserialize)]
pub struct Environment {
    /// Name of the environment
    pub name: String,

    /// Source branch used for rebuilding this environment
    pub source: String,

    /// List of branches promoted to this environment
    pub branches: Vec<String>,

    /// Whether the environment is currently locked
    pub locked: bool,

    /// Email of user who locked the environment (null if unlocked)
    pub locked_by: Option<String>,

    /// Timestamp when environment was locked (null if unlocked)
    pub locked_at: Option<DateTime<Utc>>,

    /// Timestamp when environment was last rebuilt (null if never rebuilt)
    pub rebuilt_at: Option<DateTime<Utc>>,
}

impl Environment {
    pub fn new(name: String, source: String) -> Self {
        Self {
            name,
            source,
            branches: Vec::new(),
            locked: false,
            locked_by: None,
            locked_at: None,
            rebuilt_at: None,
        }
    }

    pub fn is_locked(&self) -> bool {
        self.locked
    }

    pub fn lock(&mut self, user_email: String) {
        self.locked = true;
        self.locked_by = Some(user_email);
        self.locked_at = Some(Utc::now());
    }

    pub fn unlock(&mut self) {
        self.locked = false;
        self.locked_by = None;
        self.locked_at = None;
    }

    pub fn update_rebuilt_timestamp(&mut self) {
        self.rebuilt_at = Some(Utc::now());
    }

    pub fn add_branch(&mut self, branch: String) {
        if !self.branches.contains(&branch) {
            self.branches.push(branch);
        }
    }

    pub fn remove_branch(&mut self, branch: &str) {
        self.branches.retain(|b| b != branch);
    }

    pub fn has_branch(&self, branch: &str) -> bool {
        self.branches.contains(&branch.to_string())
    }
}

/// Main Hitch configuration structure
#[derive(Debug, Clone, Serialize, Deserialize)]
pub struct HitchConfig {
    /// Version of the configuration format
    pub version: String,

    /// Map of environment names to environment configurations
    pub environments: std::collections::HashMap<String, Environment>,
}

impl HitchConfig {
    pub fn new() -> Self {
        Self {
            version: "1.0".to_string(),
            environments: std::collections::HashMap::new(),
        }
    }

    pub fn add_environment(&mut self, environment: Environment) {
        self.environments
            .insert(environment.name.clone(), environment);
    }

    pub fn remove_environment(&mut self, name: &str) {
        self.environments.remove(name);
    }

    pub fn get_environment(&self, name: &str) -> Option<&Environment> {
        self.environments.get(name)
    }

    pub fn get_environment_mut(&mut self, name: &str) -> Option<&mut Environment> {
        self.environments.get_mut(name)
    }

    pub fn environment_exists(&self, name: &str) -> bool {
        self.environments.contains_key(name)
    }

    pub fn get_environment_names(&self) -> Vec<String> {
        self.environments.keys().cloned().collect()
    }
}

impl Default for HitchConfig {
    fn default() -> Self {
        Self::new()
    }
}

use anyhow::{Context, Result};
use colored::*;
use git2::{ObjectType, Oid, Repository};
use std::process::Command;

pub struct GitOperations {
    repo: Repository,
}

impl GitOperations {
    pub fn new() -> Result<Self> {
        let repo = Repository::discover(".").context("Not in a git repository")?;
        Ok(GitOperations { repo })
    }

    pub fn get_current_branch(&self) -> Result<String> {
        // Use git command to handle orphan branches properly
        let output = Command::new("git")
            .args(&["branch", "--show-current"])
            .output()
            .context("Failed to get current branch")?;

        if output.status.success() {
            let branch_name = String::from_utf8(output.stdout)?.trim().to_string();
            if !branch_name.is_empty() {
                Ok(branch_name)
            } else {
                // Handle detached HEAD or other states
                Err(anyhow::anyhow!("Not currently on any branch"))
            }
        } else {
            Err(anyhow::anyhow!(
                "Failed to get current branch: {}",
                String::from_utf8_lossy(&output.stderr)
            ))
        }
    }

    pub fn checkout_branch(&self, branch: &str) -> Result<()> {
        let output = Command::new("git")
            .args(&["checkout", branch])
            .output()
            .context(format!("Failed to checkout branch '{}'", branch))?;

        if !output.status.success() {
            return Err(anyhow::anyhow!(
                "Failed to checkout branch '{}': {}",
                branch,
                String::from_utf8_lossy(&output.stderr)
            ));
        }

        Ok(())
    }

    pub fn create_orphan_branch(&self, branch_name: &str) -> Result<()> {
        let output = Command::new("git")
            .args(&["checkout", "--orphan", branch_name])
            .output()
            .context(format!("Failed to create orphan branch '{}'", branch_name))?;

        if !output.status.success() {
            return Err(anyhow::anyhow!(
                "Failed to create orphan branch '{}': {}",
                branch_name,
                String::from_utf8_lossy(&output.stderr)
            ));
        }

        // Clean working directory
        let _ = Command::new("git")
            .args(&["rm", "-rf", "."])
            .output()
            .context("Failed to clean working directory")?;

        Ok(())
    }

    pub fn add_and_commit(&self, files: &[&str], message: &str) -> Result<()> {
        // Add files
        for file in files {
            let output = Command::new("git")
                .args(&["add", file])
                .output()
                .context(format!("Failed to add file '{}'", file))?;

            if !output.status.success() {
                return Err(anyhow::anyhow!(
                    "Failed to add file '{}': {}",
                    file,
                    String::from_utf8_lossy(&output.stderr)
                ));
            }
        }

        // Commit
        let output = Command::new("git")
            .args(&["commit", "-m", message])
            .output()
            .context("Failed to commit files")?;

        if !output.status.success() {
            return Err(anyhow::anyhow!(
                "Failed to commit: {}",
                String::from_utf8_lossy(&output.stderr)
            ));
        }

        Ok(())
    }

    pub fn read_file_from_branch(&self, branch: &str, file: &str) -> Result<String> {
        let output = Command::new("git")
            .args(&["show", &format!("{}:{}", branch, file)])
            .output()
            .context(format!(
                "Failed to read '{}' from branch '{}'",
                file, branch
            ))?;

        if !output.status.success() {
            return Err(anyhow::anyhow!(
                "File '{}' not found in branch '{}'",
                file,
                branch
            ));
        }

        let content = String::from_utf8(output.stdout).context("Failed to parse file content")?;

        Ok(content)
    }

    pub fn write_file(&self, file: &str, content: &str) -> Result<()> {
        std::fs::write(file, content).context(format!("Failed to write file '{}'", file))?;
        Ok(())
    }

    pub fn fetch_branch(&self, branch: &str) -> Result<()> {
        let output = Command::new("git")
            .args(&["fetch", "origin", branch])
            .output()
            .context(format!("Failed to fetch branch '{}'", branch))?;

        if !output.status.success() {
            // Don't fail if fetch fails (might not exist remotely)
            let stderr = String::from_utf8_lossy(&output.stderr);
            if !stderr.contains("couldn't find remote ref")
                && !stderr.contains("no such remote ref")
            {
                return Err(anyhow::anyhow!("Fetch failed: {}", stderr));
            }
        }

        Ok(())
    }

    pub fn push_branch(&self, branch: &str) -> Result<()> {
        let output = Command::new("git")
            .args(&["push", "origin", branch])
            .output()
            .context(format!("Failed to push branch '{}'", branch))?;

        if !output.status.success() {
            return Err(anyhow::anyhow!(
                "Failed to push branch '{}': {}",
                branch,
                String::from_utf8_lossy(&output.stderr)
            ));
        }

        Ok(())
    }

    pub fn branch_exists(&self, branch: &str) -> Result<bool> {
        let output = Command::new("git")
            .args(&["branch", "--list", branch])
            .output()
            .context("Failed to list branches")?;

        Ok(output.status.success() && !output.stdout.is_empty())
    }

    pub fn is_working_directory_clean(&self) -> Result<bool> {
        let output = Command::new("git")
            .args(&["status", "--porcelain"])
            .output()
            .context("Failed to check git status")?;

        Ok(output.stdout.is_empty())
    }

    pub fn get_user_email(&self) -> Result<String> {
        let output = Command::new("git")
            .args(&["config", "user.email"])
            .output()
            .context("Failed to get user email")?;

        if !output.status.success() {
            return Err(anyhow::anyhow!("Git user.email not configured"));
        }

        let email = String::from_utf8(output.stdout).context("Failed to parse user email")?;
        Ok(email.trim().to_string())
    }
}

use crate::commands::global_context::GlobalContext;
use crate::types::HitchConfig;
use anyhow::{Context, Result};
use colored::*;

/// Reusable pre-check function for all commands
///
/// According to the specification:
/// - Ensure the current directory is a Git repository
/// - Ensure the working tree is clean (no unstaged or uncommitted changes)
pub fn pre_check(context: &GlobalContext) -> Result<()> {
    context.log_verbose("Running pre-check validation...");

    // Check if we're in a git repository
    context.log_verbose("Checking if current directory is a Git repository...");
    if let Err(e) = context.git().get_current_branch() {
        return Err(anyhow::anyhow!(
            "Not in a Git repository. Please run this command from within a Git repository. Error: {}",
            e
        ));
    }
    context.log_verbose("✓ Git repository validation passed");

    // Check if working tree is clean
    context.log_verbose("Checking if working tree is clean...");
    let is_clean = context.git().is_working_directory_clean()?;
    if !is_clean {
        return Err(anyhow::anyhow!(
            "Working tree is not clean. Please commit or stash your changes before running this command."
        ));
    }
    context.log_verbose("✓ Working tree is clean");

    context.log_verbose("Pre-check validation completed successfully");
    Ok(())
}

/// Switch to a branch, execute a closure, and always return to the original branch
///
/// According to the specification:
/// - Record current branch
/// - Checkout target branch
/// - Execute the provided closure while on the target branch
/// - Always attempt to switch back to the original branch after the closure runs, even if it fails
pub fn switch_to<F, R>(context: &GlobalContext, target_branch: &str, closure: F) -> Result<R>
where
    F: FnOnce() -> Result<R>,
{
    context.log_verbose(&format!("Switching to branch '{}'...", target_branch));

    // Record current branch
    let original_branch = context.git().get_current_branch()?;
    context.log_verbose(&format!("Current branch recorded: {}", original_branch));

    // Checkout target branch
    context.git().checkout_branch(target_branch)?;
    context.log_verbose(&format!("Switched to branch: {}", target_branch));

    // Execute the closure
    let result = closure();

    // Always attempt to switch back to original branch
    context.log_verbose(&format!(
        "Switching back to original branch: {}",
        original_branch
    ));
    if let Err(e) = context.git().checkout_branch(&original_branch) {
        context.log_error(&format!(
            "Failed to return to original branch '{}': {}",
            original_branch, e
        ));
        context.log_warning("You may need to manually switch back to your original branch");
    } else {
        context.log_verbose(&format!(
            "Successfully returned to original branch: {}",
            original_branch
        ));
    }

    result
}

/// Access metadata from hitch-metadata branch with optional modification
///
/// According to the specification:
/// - Fetch latest hitch-metadata from remote: git fetch origin hitch-metadata
/// - Temporarily switch to the hitch-metadata branch using switch-to
/// - Load and parse hitch.json
/// - If a closure is provided, execute it with the metadata object (for modification)
/// - Any changes should be committed and optionally pushed (warn if push fails or skip with --no-push)
/// - Return metadata (updated if modified, or original if read-only)
/// - Always switch back to the original branch afterward
pub fn access_metadata<F>(context: &GlobalContext, closure: F) -> Result<()>
where
    F: FnOnce(&mut HitchConfig) -> Result<()>,
{
    context.log_verbose("Accessing hitch metadata...");

    // Check if we're already on hitch-metadata branch (for init case)
    let current_branch = context.git().get_current_branch();
    let already_on_metadata_branch =
        current_branch.is_ok() && current_branch.unwrap() == "hitch-metadata";

    if !already_on_metadata_branch {
        // Fetch latest hitch-metadata from remote
        context.log_verbose("Fetching latest hitch-metadata from remote...");
        if let Err(e) = context.git().fetch_branch("hitch-metadata") {
            context.log_warning(&format!(
                "Failed to fetch hitch-metadata from remote: {}",
                e
            ));
            context.log_warning("Continuing with local metadata...");
        }
    }

    let modification_closure = || {
        // Load and parse hitch.json
        context.log_verbose("Loading hitch.json...");
        let config_json = context
            .git()
            .read_file_from_branch("hitch-metadata", "hitch.json")
            .unwrap_or_else(|e| {
                // If file doesn't exist, create default config
                context.log_info(&format!(
                    "hitch.json not found or unreadable ({}), creating default configuration",
                    e
                ));
                let default_config = HitchConfig::new();
                serde_json::to_string_pretty(&default_config).unwrap()
            });

        let mut config: HitchConfig =
            serde_json::from_str(&config_json).context("Failed to parse hitch.json")?;

        context.log_verbose("✓ hitch.json loaded successfully");

        // Execute closure (for modification)
        context.log_verbose("Modifying metadata...");
        closure(&mut config)?;

        // Write updated config
        context.log_verbose("Writing updated hitch.json...");
        context
            .git()
            .write_file("hitch.json", &serde_json::to_string_pretty(&config)?)?;

        // Commit changes
        context.log_verbose("Committing metadata changes...");
        context
            .git()
            .add_and_commit(&["hitch.json"], "Update hitch configuration")?;

        // Optionally push
        if context.should_push() {
            context.log_verbose("Pushing metadata to remote...");
            if let Err(e) = context.git().push_branch("hitch-metadata") {
                context.log_warning(&format!("Failed to push metadata to remote: {}", e));
            } else {
                context.log_verbose("✓ Metadata pushed to remote");
            }
        } else {
            context.log_verbose("Skipping push due to --no-push flag");
        }

        Ok(())
    };

    if already_on_metadata_branch {
        context.log_verbose("Already on hitch-metadata branch, proceeding with metadata access...");
        modification_closure()
    } else {
        switch_to(context, "hitch-metadata", modification_closure)
    }
}

/// Execute operations within a locked environment context
///
/// According to the specification:
/// - Calls lock(env_name) → executes closure → calls unlock(env_name) even if closure fails
/// - Ensures environment is safely locked during modifications
/// - Automatically handles warnings if push fails
pub fn with_locked_env<F, R>(context: &GlobalContext, env_name: &str, closure: F) -> Result<R>
where
    F: FnOnce() -> Result<R>,
{
    context.log_verbose(&format!("Locking environment '{}'...", env_name));

    // Lock the environment
    lock_environment(context, env_name)?;

    // Execute the closure
    let result = closure();

    // Always unlock the environment, even if closure failed
    context.log_verbose(&format!("Unlocking environment '{}'...", env_name));
    if let Err(e) = unlock_environment(context, env_name) {
        context.log_warning(&format!(
            "Failed to unlock environment '{}': {}",
            env_name, e
        ));
        context.log_warning("You may need to manually unlock the environment");
    } else {
        context.log_verbose(&format!(
            "✓ Environment '{}' unlocked successfully",
            env_name
        ));
    }

    result
}

/// Lock an environment
fn lock_environment(context: &GlobalContext, env_name: &str) -> Result<()> {
    access_metadata(context, |config: &mut HitchConfig| {
        let environment = config
            .get_environment_mut(env_name)
            .ok_or_else(|| anyhow::anyhow!("Environment '{}' not found", env_name))?;

        if environment.is_locked() {
            return Err(anyhow::anyhow!(
                "Environment '{}' is already locked by {}",
                env_name,
                environment
                    .locked_by
                    .as_ref()
                    .unwrap_or(&"unknown".to_string())
            ));
        }

        let user_email = context.git().get_user_email()?;
        environment.lock(user_email.clone());

        context.log_info(&format!(
            "Environment '{}' locked by {}",
            env_name, user_email
        ));
        Ok(())
    })
}

/// Unlock an environment
fn unlock_environment(context: &GlobalContext, env_name: &str) -> Result<()> {
    access_metadata(context, |config: &mut HitchConfig| {
        let environment = config
            .get_environment_mut(env_name)
            .ok_or_else(|| anyhow::anyhow!("Environment '{}' not found", env_name))?;

        if !environment.is_locked() {
            context.log_info(&format!("Environment '{}' is already unlocked", env_name));
            return Ok(());
        }

        environment.unlock();

        context.log_info(&format!("Environment '{}' unlocked", env_name));
        Ok(())
    })
}

